insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_deceive','deceive','verb','to make someone believe something that is not true','[{"senseId":"deceive_1","meaning":"to make someone believe something that is not true","acceptedParaphrases":["mislead","trick"],"masteryContexts":[{"contextId":"u3_21_deceive_meaning","text":"Some websites use fake reviews to deceive customers into buying poor products.","meaning":"make people believe something false","wrongMeanings":["persuade people to give money to charity","warn people about unsafe products","help people to find cheaper goods"]},{"contextId":"u3_21_deceive_paraphrase","text":"It is wrong to deceive customers about what is in a product, so the law requires honest labels.","meaning":"give people a false idea","wrongMeanings":["teach customers about healthy eating","ask customers about their opinions","refuse to serve customers at all"]}],"situationDistractors":["The waiter described each dish honestly and answered every question about the food.","The chef showed the customers exactly how the burger was cooked.","The label listed every ingredient clearly, from the largest amount to the smallest.","The shop owner admitted the mistake and gave customers their money back.","The poster showed the real price in large clear numbers.","The manager told the staff to speak politely to every guest."],"gapDistractors":[{"contextId":"u3_21_deceive_gap_1","answer":"deceive","wrong":["thank","reward","invite"]},{"contextId":"u3_21_deceive_gap_2","answer":"deceive","wrong":["advise","thank","invite"]},{"contextId":"u3_21_deceive_gap_3","answer":"deceive","wrong":["remind","excuse","greet"]}],"spellingErrors":["decieve","deceeve","deseive","deceave","decive","deceiv"],"wordFamilyForms":[{"form":"deceive","partOfSpeech":"verb","example":"Some websites deceive customers with fake reviews.","pedagogicallyUseful":true},{"form":"deception","partOfSpeech":"noun","example":"The cheating was a clear case of deception, and customers lost trust in the brand.","pedagogicallyUseful":true,"altExample":"The shop owner admitted the deception and gave customers their money back."},{"form":"deceptive","partOfSpeech":"adjective","example":"The photograph on the menu was deceptive, because the real dish was much smaller.","pedagogicallyUseful":true,"altExample":"The label was deceptive, because the juice contained almost no fruit."}],"masteryPassages":[{"passageId":"u3_21_deceive_passage_1","contextId":"u3_21_deceive_gap_1","text":"Some adverts use clever photographs. Their aim is to ____ customers, because the real meal looks much smaller than the picture.","answer":"deceive"},{"passageId":"u3_21_deceive_passage_2","contextId":"u3_21_deceive_gap_2","text":"Honest shopkeepers never try to ____ their customers. They tell the truth about where the food comes from and what it contains.","answer":"deceive"}],"contextDependentParaphrases":[],"wrongParaphrases":["warn","thank","persuade"],"misleadingDistractors":["to warn someone about a danger","to ask someone for their opinion","to teach someone a new skill"],"grammarForms":{"base":"deceive","thirdPerson":"deceives","past":"deceived","pastParticiple":"deceived","ing":"deceiving"}}]'::jsonb,'["deception","deceptive"]'::jsonb,'["deceive customers","deceive people","easily deceive"]'::jsonb,'live'),
('vocab_advertisement','advertisement','noun','a notice, picture or film that tries to persuade people to buy something','[{"senseId":"advertisement_1","meaning":"a notice, picture or film that tries to persuade people to buy something","acceptedParaphrases":["advert","message to sell a product"],"masteryContexts":[{"contextId":"u3_22_advertisement_meaning","text":"The advertisement showed a happy family sharing a pizza at the dinner table.","meaning":"a picture or film that tries to sell something","wrongMeanings":["a report that explains how a pizza is made","a menu that lists the dishes in a restaurant","a bill that shows how much a family must pay"]},{"contextId":"u3_22_advertisement_paraphrase","text":"Chocolate companies spend millions of pounds on every advertisement they put on television.","meaning":"a message that tries to make people buy a product","wrongMeanings":["a letter that thanks customers for their custom","a list of the goods that a shop has in stock","a notice that warns people about a danger"]}],"situationDistractors":["The newspaper printed a long report about a school sports day.","The waiter handed the family the bill at the end of the meal.","The chef posted the recipe on a cooking website for free.","The restaurant printed a menu with the day’s dishes.","A customer wrote a review of the cafe on the internet.","The cashier gave the customer a receipt."],"gapDistractors":[{"contextId":"u3_22_advertisement_gap_1","answer":"advertisement","wrong":["recipe","receipt","invoice"]},{"contextId":"u3_22_advertisement_gap_2","answer":"advertisement","wrong":["recipe","receipt","invoice"]},{"contextId":"u3_22_advertisement_gap_3","answer":"advertisement","wrong":["recipe","menu","receipt"]}],"spellingErrors":["advertisment","advertizement","adverticement","advertisemant","adversisement","advertismant"],"wordFamilyForms":[{"form":"advertisement","partOfSpeech":"noun","example":"The advertisement showed the burger far larger than it really is.","pedagogicallyUseful":true},{"form":"advertise","partOfSpeech":"verb","example":"Fast-food companies advertise their products during children’s programmes.","pedagogicallyUseful":true,"altExample":"Companies must not advertise food with false claims."},{"form":"advertising","partOfSpeech":"noun","example":"Food advertising aimed at children is controlled by law in many countries.","pedagogicallyUseful":true,"altExample":"The company spends millions of pounds on advertising every year."}],"masteryPassages":[{"passageId":"u3_22_advertisement_passage_1","contextId":"u3_22_advertisement_gap_1","text":"Last night, a colourful ____ for a new burger appeared between two television programmes. It showed smiling people, a low price and the shop’s address.","answer":"advertisement"},{"passageId":"u3_22_advertisement_passage_2","contextId":"u3_22_advertisement_gap_2","text":"The restaurant wanted more customers. It put an ____ in the local newspaper, with a photograph of its most popular dish and a special offer.","answer":"advertisement"}],"contextDependentParaphrases":[],"wrongParaphrases":["review","recipe","receipt"],"misleadingDistractors":["a short report about a news event","a list of the prices of goods","a letter that thanks a customer"]}]'::jsonb,'["advertise","advertising"]'::jsonb,'["television advertisement","newspaper advertisement","online advertisement"]'::jsonb,'live'),
('vocab_variety','variety','noun','a number of different kinds of the same thing','[{"senseId":"variety_1","meaning":"a number of different kinds of the same thing","acceptedParaphrases":["range","selection"],"masteryContexts":[{"contextId":"u3_23_variety_meaning","text":"The buffet offers a wide variety of dishes from different countries.","meaning":"many different kinds of something","wrongMeanings":["a small amount of food that is served first","a single type of dish that is always the same","a long list of rules for a kitchen"]},{"contextId":"u3_23_variety_paraphrase","text":"Customers love the variety at the market, where every stall sells something different.","meaning":"a lot of different things to choose from","wrongMeanings":["a lack of choice in a shop","a high price for goods","a feeling of being tired and bored"]}],"situationDistractors":["The cafe sells only one kind of sandwich and nothing else.","Every stall at the market sold exactly the same cheese.","The menu had a single dish, which never changed.","The restaurant was full of customers on Saturday night.","The cook washed all the vegetables in cold water.","The shop closes at six o’clock on weekdays."],"gapDistractors":[{"contextId":"u3_23_variety_gap_1","answer":"variety","wrong":["price","speed","level"]},{"contextId":"u3_23_variety_gap_2","answer":"variety","wrong":["price","speed","level"]},{"contextId":"u3_23_variety_gap_3","answer":"variety","wrong":["shortage","habit","absence"]}],"spellingErrors":["variaty","varity","varietey","vareity","verity","varriety"],"wordFamilyForms":[{"form":"variety","partOfSpeech":"noun","example":"The market has a great variety of fresh fish.","pedagogicallyUseful":true},{"form":"vary","partOfSpeech":"verb","example":"Prices of vegetables vary from season to season.","pedagogicallyUseful":true,"altExample":"The taste of the soup can vary depending on the chef."},{"form":"various","partOfSpeech":"adjective","example":"The cafe serves various kinds of soup.","pedagogicallyUseful":true,"altExample":"We tried various dishes at the street food festival."}],"masteryPassages":[{"passageId":"u3_23_variety_passage_1","contextId":"u3_23_variety_gap_1","text":"There is a huge ____ of food at the festival. Stalls sell noodles, tacos, pancakes, sushi and ice cream from many countries.","answer":"variety"},{"passageId":"u3_23_variety_passage_2","contextId":"u3_23_variety_gap_2","text":"Eating the same lunch every day can become boring. A good meal plan includes a ____ of vegetables, so that each day brings new colours and flavours.","answer":"variety"}],"contextDependentParaphrases":[],"wrongParaphrases":["shortage","copy","habit"],"misleadingDistractors":["a single kind of something that is sold","a plan for how something will be made","a feeling that something is boring"]}]'::jsonb,'["vary","various"]'::jsonb,'["wide variety","great variety","huge variety"]'::jsonb,'live'),
('vocab_portion','portion','noun','the amount of food served to one person','[{"senseId":"portion_1","meaning":"the amount of food served to one person","acceptedParaphrases":["serving","helping"],"masteryContexts":[{"contextId":"u3_24_portion_meaning","text":"A child’s portion at the restaurant is smaller and cheaper than an adult’s.","meaning":"the amount of food served to one person","wrongMeanings":["the whole amount of food made in a kitchen","the price that a customer pays for a meal","the list of dishes on offer"]},{"contextId":"u3_24_portion_paraphrase","text":"The dish comes with a free portion of rice, so you do not have to order any extra.","meaning":"an amount of food for one person","wrongMeanings":["a part of a restaurant for large groups","a rule about how to eat politely","the person who brings the food"]}],"situationDistractors":["The chef cooked enough soup to feed two hundred guests at the wedding.","The waiter wrote down the number of each table.","The bill showed the total price for the whole meal.","The manager asked the cooks to clean the kitchen at closing time.","A large pot of beans was kept warm on the stove.","The customer asked for the menu and a glass of water."],"gapDistractors":[{"contextId":"u3_24_portion_gap_1","answer":"portion","wrong":["recipe","receipt","menu"]},{"contextId":"u3_24_portion_gap_2","answer":"portion","wrong":["recipe","receipt","price"]},{"contextId":"u3_24_portion_gap_3","answer":"portion","wrong":["recipe","receipt","dessert"]}],"spellingErrors":["porshun","portian","porsion","portoin","porttion","protion"],"masteryPassages":[{"passageId":"u3_24_portion_passage_1","contextId":"u3_24_portion_gap_1","text":"The restaurant gives each guest a very generous ____ of rice. Many people take some home in a box.","answer":"portion"},{"passageId":"u3_24_portion_passage_2","contextId":"u3_24_portion_gap_2","text":"Nutrition labels show the size of one ____. Shoppers can then compare how much sugar is in the amount a person usually eats.","answer":"portion"}],"contextDependentParaphrases":[],"wrongParaphrases":["recipe","receipt","menu"],"misleadingDistractors":["the whole amount of food in a large dish","a small part of a restaurant where people wait","the money paid for a meal"]}]'::jsonb,'[]'::jsonb,'["large portion","small portion","generous portion"]'::jsonb,'live'),
('vocab_purchase','purchase','noun','something that you have bought','[{"senseId":"purchase_1","meaning":"something that you have bought","acceptedParaphrases":["thing bought","an item you bought"],"masteryContexts":[{"contextId":"u3_25_purchase_meaning","text":"Her biggest purchase this month was a new oven for the family kitchen.","meaning":"a thing that was bought","wrongMeanings":["a machine that cooks food quickly","a gift that a customer received","a list of things that a shop sells"]},{"contextId":"u3_25_purchase_paraphrase","text":"Every purchase over ten pounds at the cafe earns you a stamp towards a free coffee.","meaning":"an act of buying something","wrongMeanings":["a refund for goods that were returned","an order that a cook receives","an offer that a shop makes"]}],"situationDistractors":["The customer returned the faulty kettle and asked for her money back.","A friend gave him a box of chocolates for his birthday.","The shop was having a sale, but the doors were locked.","He read the menu twice before deciding what to eat.","The cashier counted the notes in the till.","They borrowed a table from a neighbour for the party."],"gapDistractors":[{"contextId":"u3_25_purchase_gap_1","answer":"purchase","wrong":["dish","recipe","guest"]},{"contextId":"u3_25_purchase_gap_2","answer":"purchase","wrong":["recipe","dish","guest"]},{"contextId":"u3_25_purchase_gap_3","answer":"purchase","wrong":["recipe","dish","speech"]}],"spellingErrors":["purchese","perchase","purchace","purchass","purcase","purchasse"],"masteryPassages":[{"passageId":"u3_25_purchase_passage_1","contextId":"u3_25_purchase_gap_1","text":"Tom saved his pocket money for weeks. His first big ____ was a set of kitchen knives, and he was proud to carry them home.","answer":"purchase"},{"passageId":"u3_25_purchase_passage_2","contextId":"u3_25_purchase_gap_2","text":"Before you pay, check the price on the shelf. After every ____ in a supermarket, keep the receipt, because it proves what you paid.","answer":"purchase"}],"contextDependentParaphrases":[],"wrongParaphrases":["thing sold","thing borrowed","thing stolen"],"misleadingDistractors":["a list of goods that a shop has for sale","the money that you save each month","a small gift that a shop gives away"]}]'::jsonb,'[]'::jsonb,'["online purchase","recent purchase","major purchase"]'::jsonb,'live'),
('vocab_takeaway','takeaway','noun','a meal that you buy at a restaurant and eat somewhere else','[{"senseId":"takeaway_1","meaning":"a meal that you buy at a restaurant and eat somewhere else","acceptedParaphrases":["meal to take home","food to go"],"masteryContexts":[{"contextId":"u3_26_takeaway_meaning","text":"There is a Chinese takeaway on the corner of our street that stays open until midnight.","meaning":"a shop that sells hot meals to eat elsewhere","wrongMeanings":["a restaurant with tables and waiters","a market that sells fruit","a school for cooks"]},{"contextId":"u3_26_takeaway_paraphrase","text":"On Fridays we usually order a takeaway instead of cooking.","meaning":"a meal bought to eat at home","wrongMeanings":["a meal that the family cooks together","a main idea from a conversation","a dish that has been left over"]}],"situationDistractors":["We sat at a table in the restaurant while the waiter brought each course.","She cooked a pot of soup at home for the whole family.","The guests ate the wedding meal in the hotel dining room.","The shop sold fresh vegetables, eggs and milk to local families.","The school canteen served lunch to the pupils at noon.","He packed sandwiches from home for the trip."],"gapDistractors":[{"contextId":"u3_26_takeaway_gap_1","answer":"takeaway","wrong":["library","cinema","stadium"]},{"contextId":"u3_26_takeaway_gap_2","answer":"takeaway","wrong":["recipe","lesson","jacket"]},{"contextId":"u3_26_takeaway_gap_3","answer":"takeaway","wrong":["library","cinema","museum"]}],"spellingErrors":["takeway","takaway","takeawy","takeawai","takaweay","takeaaway"],"masteryPassages":[{"passageId":"u3_26_takeaway_passage_1","contextId":"u3_26_takeaway_gap_1","text":"Neither of my parents had time to cook last night. Dad phoned the Indian restaurant and collected a ____ on his way home.","answer":"takeaway"},{"passageId":"u3_26_takeaway_passage_2","contextId":"u3_26_takeaway_gap_2","text":"I do not like waiting for a table. When I am in a hurry, I order a ____ so that I can eat at home or in the park.","answer":"takeaway"}],"contextDependentParaphrases":[],"wrongParaphrases":["meal to eat here","meal to cook yourself","meal to send abroad"],"misleadingDistractors":["a meal that is served at a table by a waiter","a main point that you remember from a talk","a shop that sells only fruit and vegetables"]}]'::jsonb,'[]'::jsonb,'["Chinese takeaway","order takeaway","takeaway food"]'::jsonb,'live'),
('vocab_barbecue','barbecue','noun','an outdoor meal where food is cooked over a fire or on a grill','[{"senseId":"barbecue_1","meaning":"an outdoor meal where food is cooked over a fire or on a grill","acceptedParaphrases":["grill party","outdoor cooking party"],"masteryContexts":[{"contextId":"u3_27_barbecue_meaning","text":"We had a barbecue on the beach and cooked sausages over a small fire.","meaning":"an outdoor meal cooked over a fire","wrongMeanings":["a quiet dinner in a formal restaurant","a cold picnic eaten in a park","a cooking lesson held at school"]},{"contextId":"u3_27_barbecue_paraphrase","text":"Dad cleaned the barbecue before our guests arrived and checked that it had enough charcoal.","meaning":"a metal frame used for cooking food outside","wrongMeanings":["a metal bowl used for mixing food","a machine that freezes food quickly","a cupboard used for storing plates"]}],"situationDistractors":["The guests ate cold sandwiches at a small table in a hotel restaurant.","The chef baked the cake in a large oven in the school kitchen.","The family had dinner indoors at the dining table while it rained.","The class watched a film about how bread is made.","He boiled the eggs in a small pan on the stove.","The pupils ate lunch in the canteen."],"gapDistractors":[{"contextId":"u3_27_barbecue_gap_1","answer":"barbecue","wrong":["lesson","meeting","concert"]},{"contextId":"u3_27_barbecue_gap_2","answer":"barbecue","wrong":["classroom","library","bedroom"]},{"contextId":"u3_27_barbecue_gap_3","answer":"barbecue","wrong":["lesson","test","concert"]}],"spellingErrors":["barbeque","barbecu","barbacue","barbeceu","barbequ","barbicue"],"masteryPassages":[{"passageId":"u3_27_barbecue_passage_1","contextId":"u3_27_barbecue_gap_1","text":"The weather forecast promised a hot Saturday. Our neighbours invited everyone to a ____ in their garden, where they cooked burgers and corn over hot coals.","answer":"barbecue"},{"passageId":"u3_27_barbecue_passage_2","contextId":"u3_27_barbecue_gap_2","text":"My uncle lit the charcoal and put the chicken on the metal frame. At our family ____, everyone eats outside and shares food from the same table.","answer":"barbecue"}],"contextDependentParaphrases":[],"wrongParaphrases":["picnic lunch","school dinner","tea party"],"misleadingDistractors":["a formal dinner served in a restaurant","a picnic of cold food in a park","a cooking class held in a school kitchen"]}]'::jsonb,'[]'::jsonb,'["garden barbecue","summer barbecue","charcoal barbecue"]'::jsonb,'live'),
('vocab_saturated','saturated','adjective','describing the type of fat found mainly in butter, cheese and fatty meat','[{"senseId":"saturated_1","meaning":"describing the type of fat found mainly in butter, cheese and fatty meat","acceptedParaphrases":["the type of fat found in butter","the kind of fat in fatty meat and dairy foods"],"masteryContexts":[{"contextId":"u3_28_saturated_meaning","text":"Butter, cheese and fatty meat are high in saturated fat.","meaning":"describing the type of fat found in butter and meat","wrongMeanings":["describing a fat that stays liquid in the fridge","describing food that is completely wet","describing a fat that has no taste"]},{"contextId":"u3_28_saturated_paraphrase","text":"The label says that one portion of the pizza contains a lot of saturated fat.","meaning":"of the type of fat found in butter and meat","wrongMeanings":["full of water after heavy rain","sweet and sticky after cooking","very hot after frying"]}],"situationDistractors":["The cook poured olive oil, which stays liquid in the fridge, over the salad.","The nutritionist recommended eating more fruit and fish.","The cook trimmed all the fat off the meat before grilling it.","The label listed the vitamins in the juice.","The salad contained lettuce, tomato and cucumber.","The baker cooled the bread on a wire rack."],"gapDistractors":[{"contextId":"u3_28_saturated_gap_1","answer":"saturated","wrong":["liquid","spicy","sugary"]},{"contextId":"u3_28_saturated_gap_2","answer":"saturated","wrong":["spicy","sugary","liquid"]},{"contextId":"u3_28_saturated_gap_3","answer":"saturated","wrong":["spicy","sugary","sweet"]}],"spellingErrors":["saturaded","satturated","saturatid","saterated","saturted","sarurated"],"masteryPassages":[{"passageId":"u3_28_saturated_passage_1","contextId":"u3_28_saturated_gap_1","text":"Pupils in the food technology class compared two foods. Butter contains much more ____ fat than olive oil, and it stays hard in the fridge.","answer":"saturated"},{"passageId":"u3_28_saturated_passage_2","contextId":"u3_28_saturated_gap_2","text":"The nutrition label has a line for fat and another line for ____ fat. The second line is smaller, because it shows only the fat that comes mainly from animal foods such as cheese.","answer":"saturated"}],"contextDependentParaphrases":[],"wrongParaphrases":["the type of oil found in olives","the type of sugar found in fruit","the type of salt found in the sea"],"misleadingDistractors":["describing oil that stays liquid in the fridge","describing food that has been fried for a long time","describing fat that has been removed from meat"]}]'::jsonb,'[]'::jsonb,'["saturated fat","saturated fats","mostly saturated"]'::jsonb,'live'),
('vocab_convenient','convenient','adjective','easy to use or suitable because it saves time or effort','[{"senseId":"convenient_1","meaning":"easy to use or suitable because it saves time or effort","acceptedParaphrases":["handy","easy to use"],"masteryContexts":[{"contextId":"u3_29_convenient_meaning","text":"The supermarket is open until midnight, which is convenient for people who work late.","meaning":"suitable because it saves time or effort","wrongMeanings":["popular because it sells cheap food","large enough for many customers","pleasant because it has a garden"]},{"contextId":"u3_29_convenient_paraphrase","text":"A restaurant near the station is convenient because you can eat before you catch the train.","meaning":"easy to reach and useful","wrongMeanings":["expensive because it is in the city","crowded because it is lunchtime","open only at weekends"]}],"situationDistractors":["The only shop was twenty kilometres away, and there was no bus.","The restaurant was so far from the station that diners missed their trains.","The recipe took four hours and needed twelve different pans.","The opening hours changed every week, so customers never knew when it was open.","The tiny kitchen had no space for a fridge.","The queue stretched all the way down the street."],"gapDistractors":[{"contextId":"u3_29_convenient_gap_1","answer":"convenient","wrong":["curious","confident","cautious"]},{"contextId":"u3_29_convenient_gap_2","answer":"convenient","wrong":["jealous","generous","anxious"]},{"contextId":"u3_29_convenient_gap_3","answer":"convenient","wrong":["famous","honest","polite"]}],"spellingErrors":["convienient","convinient","conveniant","convenint","conveneint","convenent"],"wordFamilyForms":[{"form":"convenient","partOfSpeech":"adjective","example":"Frozen peas are convenient because they keep for months.","pedagogicallyUseful":true},{"form":"convenience","partOfSpeech":"noun","example":"Online shopping offers great convenience to people with busy lives.","pedagogicallyUseful":true,"altExample":"The convenience of online ordering means you never have to queue."},{"form":"conveniently","partOfSpeech":"adverb","example":"The cafe is conveniently located next to the bus station.","pedagogicallyUseful":true,"altExample":"The supermarket is conveniently open until midnight."}],"masteryPassages":[{"passageId":"u3_29_convenient_passage_1","contextId":"u3_29_convenient_gap_1","text":"Kim has a very busy week with little time to shop. She likes the small supermarket near her flat, because it is open late and she can buy dinner on her way home. It is a very ____ shop.","answer":"convenient"},{"passageId":"u3_29_convenient_passage_2","contextId":"u3_29_convenient_gap_2","text":"Ready-to-heat meals are popular with busy families. They are not always the cheapest choice, but they are ____ because they save time in the kitchen.","answer":"convenient"}],"contextDependentParaphrases":[],"wrongParaphrases":["costly","crowded","tasty"],"misleadingDistractors":["cheap enough for everyone to buy","healthy enough for every meal","large enough for a big family"]}]'::jsonb,'["convenience","conveniently"]'::jsonb,'["very convenient","more convenient","convenient time"]'::jsonb,'live'),
('vocab_extensive','extensive','adjective','covering a large area or including many things','[{"senseId":"extensive_1","meaning":"covering a large area or including many things","acceptedParaphrases":["wide-ranging","very large"],"masteryContexts":[{"contextId":"u3_30_extensive_meaning","text":"The farm has extensive fields where vegetables are grown for the local market.","meaning":"covering a large area","wrongMeanings":["divided into small private gardens","covered by thick forest","close to the busy town centre"]},{"contextId":"u3_30_extensive_paraphrase","text":"After extensive research, the company changed its recipe to use less sugar.","meaning":"thorough and including many details","wrongMeanings":["quick and without much care","secret and unfinished","expensive and inaccurate"]}],"situationDistractors":["The tiny cafe had room for only four tables.","The menu offered just three dishes, and they changed very rarely.","The shop sold a few kinds of bread and nothing else.","The survey asked only five pupils one question about breakfast.","The recipe was short and needed just three ingredients.","The garden behind the restaurant had one small herb pot."],"gapDistractors":[{"contextId":"u3_30_extensive_gap_1","answer":"extensive","wrong":["limited","tiny","narrow"]},{"contextId":"u3_30_extensive_gap_2","answer":"extensive","wrong":["tiny","narrow","limited"]},{"contextId":"u3_30_extensive_gap_3","answer":"extensive","wrong":["quick","casual","lucky"]}],"spellingErrors":["extencive","extensiv","extenisve","extentive","extensife","estensive"],"wordFamilyForms":[{"form":"extensive","partOfSpeech":"adjective","example":"The restaurant has an extensive menu with over a hundred dishes.","pedagogicallyUseful":true},{"form":"extent","partOfSpeech":"noun","example":"The report studied the extent of food waste in the school canteen.","pedagogicallyUseful":true,"altExample":"To some extent, the price of fish depends on the weather."},{"form":"extensively","partOfSpeech":"adverb","example":"The chef has travelled extensively to learn about street food.","pedagogicallyUseful":true,"altExample":"The scientist has written extensively about school meals."}],"masteryPassages":[{"passageId":"u3_30_extensive_passage_1","contextId":"u3_30_extensive_gap_1","text":"Wei wanted to be a chef, so he read widely about cooking. His ____ knowledge of world cuisines impressed the judges at the competition.","answer":"extensive"},{"passageId":"u3_30_extensive_passage_2","contextId":"u3_30_extensive_gap_2","text":"The hotel has a huge garden with fruit trees, vegetable beds and a lake. Guests enjoy walking in the ____ grounds before dinner.","answer":"extensive"}],"contextDependentParaphrases":[],"wrongParaphrases":["narrow","brief","costly"],"misleadingDistractors":["costing a lot of money to produce","lasting only a short time","difficult for most people to understand"]}]'::jsonb,'["extent","extensively"]'::jsonb,'["extensive research","extensive menu","extensive range"]'::jsonb,'live')
